package com.movieworth.api.ingestion;
import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;import com.fasterxml.jackson.databind.JsonNode;import java.util.*;import java.time.LocalDate;import java.math.BigDecimal;
@Component public class AuthorizedJsonFeedClient implements BoxOfficeFeedClient{private final String url,token;private final RestClient client=RestClient.create();public AuthorizedJsonFeedClient(@Value("${movieworth.box-office.feed-url}")String u,@Value("${movieworth.box-office.feed-token}")String t){url=u;token=t;}public List<FeedRecord> fetchDaily(){if(url==null||url.isBlank())throw new IllegalStateException("Authorized feed URL missing");JsonNode root=client.get().uri(url).header("Authorization","Bearer "+token).retrieve().body(JsonNode.class);List<FeedRecord> out=new ArrayList<>();if(root!=null&&root.isArray())for(JsonNode n:root){out.add(new FeedRecord(n.path("tmdbId").asLong(),LocalDate.parse(n.path("date").asText()),decimal(n,"indiaNetCr"),decimal(n,"indiaGrossCr"),decimal(n,"overseasCr"),decimal(n,"worldwideCr"),n.path("sourceUrl").asText(null)));}return out;}private BigDecimal decimal(JsonNode n,String f){return n.hasNonNull(f)?n.get(f).decimalValue():null;}}
